  return {
      'mean_length': tf.math.reduce_mean(features['lengths']),
      'length_ranges': tf.ragged.range(features['lengths'])} 
transformed_dataset = dataset.map(transform_lengths)
print_dictionary_dataset(transformed_dataset)

